/* n-th T-derivative of  a*tanh((T - T0)/dT) + b */
template <typename S>
S entropyTanh(int order, const S &a, const S &b, const S &T0, const S &dT, const S &T) {
  using std::cosh;
  using std::erf;
  using std::exp;
  using std::pow;
  using std::sqrt;
  using std::tanh;
  switch (order) {
  case 0: {
    return a*tanh((T - T0)/dT) + b;
  }
  case 1: {
    const S x0 = 1.0/dT;
    return a*x0/pow(cosh(x0*(T - T0)), 2);
  }
  case 2: {
    const S x0 = tanh((T - T0)/dT);
    return 2*a*x0*(pow(x0, 2) - 1)/pow(dT, 2);
  }
  case 3: {
    const S x0 = pow(tanh((T - T0)/dT), 2);
    return -2*a*(x0 - 1)*(3*x0 - 1)/pow(dT, 3);
  }
  case 4: {
    const S x0 = tanh((T - T0)/dT);
    const S x1 = pow(x0, 2);
    return 8*a*x0*(x1 - 1)*(3*x1 - 2)/pow(dT, 4);
  }
  default: return S(0);
  }
}

