    const S x10 = (1.0/2.0)*x9/pow(p6, 2);
    const S x11 = exp(-x10);
    const S x12 = erf(p7*x6*x8/p6) + 1;
    const S x13 = M_1_PI;
    const S x14 = pow(p2, -6);
    const S x15 = exp(-pow(alpha1, 2)*x4);
    const S x16 = pow(p6, -6);
    const S x17 = exp(-pow(p7, 2)*x10);
    const S x18 = p0*x5;
    const S x19 = x13*x15*x18*pow(x2, 3)/pow(p2, 8);
    const S x20 = 4*x19;
    const S x21 = pow(alpha1, 3);
    const S x22 = pow(alpha1, 5);
    const S x23 = p4*x11;
    const S x24 = x13*x17*x23*pow(x8, 3)/pow(p6, 8);
    const S x25 = 4*x24;
    const S x26 = pow(p7, 3);
    const S x27 = pow(p7, 5);
    const S x28 = 3*x0*x1;
    return -pow(alpha1, 7)*x19 + 12*alpha1*p0*x13*x14*x15*x2*x5 - alpha1*x20 + 10*p0*x13*x14*x15*x2*x21*x5 + 3*p0*x13*x14*x15*x2*x22*x5 + (3.0/2.0)*p0*x0*x1*x5*x7/pow(p2, 5) + (1.0/2.0)*p0*x0*x1*pow(x2, 4)*x5*x7/pow(p2, 9) + 12*p4*p7*x11*x13*x16*x17*x8 + 10*p4*x11*x13*x16*x17*x26*x8 + 3*p4*x11*x13*x16*x17*x27*x8 + (3.0/2.0)*p4*x0*x1*x11*x12/pow(p6, 5) + (1.0/2.0)*p4*x0*x1*x11*x12*pow(x8, 4)/pow(p6, 9) - pow(p7, 7)*x24 - p7*x25 - 6*x19*x21 - x20*x22 - 6*x24*x26 - x25*x27 - x12*x23*x28*x9/pow(p6, 7) - x18*x28*x3*x7/pow(p2, 7);
